import{_ as t,o as h,c as i,a2 as c}from"./chunks/framework.mRCPFc5l.js";const l=JSON.parse('{"title":"Direct Instruction","description":"","frontmatter":{},"headers":[],"relativePath":"ideas/direct-instruction.md","filePath":"ideas/direct-instruction.md"}'),a={name:"ideas/direct-instruction.md"};function r(o,n,g,u,e,s){return h(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="direct-instruction" tabindex="-1">Direct Instruction <a class="header-anchor" href="#direct-instruction" aria-label="Permalink to &quot;Direct Instruction&quot;">​</a></h1><p>Trên trang này# Direct Instruction <a href="#direct-instruction">​</a> Dạy thẳng, rõ ràng, có trình tự: giải thích — làm mẫu — cùng làm — tự làm. Không để learner mò mẫm ra thứ có thể nói thẳng trong ba phút. Cái tên nghe cũ kỹ và bị gắn với hình ảnh lớp học thụ động, nhưng đây là một trong những cách dạy có bằng chứng hiệu quả vững nhất — đặc biệt với người mới bắt đầu và với những học sinh đang gặp khó khăn.</p><h2 id="bai-toan-no-sinh-ra-đe-giai-​" tabindex="-1">Bài toán nó sinh ra để giải <a href="#bai-toan-no-sinh-ra-đe-giai">​</a> <a class="header-anchor" href="#bai-toan-no-sinh-ra-đe-giai-​" aria-label="Permalink to &quot;Bài toán nó sinh ra để giải [​](#bai-toan-no-sinh-ra-đe-giai)&quot;">​</a></h2><p>Learner chưa có nền bị thả vào tự khám phá thường không khám phá ra gì. Tệ hơn, họ tự rút ra những quy luật sai và tin vào chúng — và một hiểu lầm được tự mình xây dựng thì rất khó gỡ về sau. Direct instruction nói: với kiến thức nền, cách nhanh nhất và ít rủi ro nhất là <strong>dạy thẳng, có cấu trúc, kiểm tra liên tục</strong>.</p><h2 id="trinh-tu-​" tabindex="-1">Trình tự <a href="#trinh-tu">​</a> <a class="header-anchor" href="#trinh-tu-​" aria-label="Permalink to &quot;Trình tự [​](#trinh-tu)&quot;">​</a></h2><p>text1. Nêu rõ hôm nay học gì và làm được gì sau bài này 2. Ôn nhanh kiến thức nền cần thiết 3. Giải thích, chia thành các bước nhỏ 4. Làm mẫu — nói to ra suy nghĩ của mình trong lúc làm 5. Cùng làm — cả lớp làm chung, có hỗ trợ dày 6. Kiểm tra hiểu — hỏi nhiều, hỏi liên tục, không hỏi &quot;các em hiểu chưa?&quot; 7. Tự làm — độc lập, ít hỗ trợ dần 8. Ôn lại có giãn cách trong các buổi sauBước 4 và bước 6 là hai bước hay bị bỏ, và cũng là hai bước quan trọng nhất. <strong>Nói to suy nghĩ trong lúc làm mẫu</strong> khác hẳn với trình bày lời giải. Không phải &quot;bước một, đặt ẩn x&quot; mà là <em>&quot;đề cho hai đại lượng chưa biết và một quan hệ giữa chúng — đây là dấu hiệu tôi nên đặt ẩn. Đặt ẩn cho cái nào? Cái xuất hiện nhiều nhất, để phương trình gọn.&quot;</em> Cái được truyền đi là <strong>cách quyết định</strong>, không phải các bước. <strong>&quot;Các em hiểu chưa?&quot;</strong> là câu hỏi vô dụng: ai cũng gật, kể cả người không hiểu. Thay bằng câu hỏi cụ thể mà chỉ người hiểu mới trả lời được.</p><h2 id="vi-sao-no-hieu-qua-​" tabindex="-1">Vì sao nó hiệu quả <a href="#vi-sao-no-hieu-qua">​</a> <a class="header-anchor" href="#vi-sao-no-hieu-qua-​" aria-label="Permalink to &quot;Vì sao nó hiệu quả [​](#vi-sao-no-hieu-qua)&quot;">​</a></h2><p>Vì trí nhớ làm việc của con người rất hẹp. Người mới học phải cùng lúc gánh: đề nói gì, dùng cái gì, đang thử hướng nào, bước vừa rồi đúng chưa. Sức chứa cạn trước khi việc học kịp xảy ra. Direct instruction gỡ tải đó bằng cách chia nhỏ, làm mẫu rõ, và cho phản hồi ngay khi vừa sai — trước khi cái sai kịp bám lại thành thói quen.</p><h2 id="yeu-o-đau-​" tabindex="-1">Yếu ở đâu <a href="#yeu-o-đau">​</a> <a class="header-anchor" href="#yeu-o-đau-​" aria-label="Permalink to &quot;Yếu ở đâu [​](#yeu-o-đau)&quot;">​</a></h2><p><strong>Với người đã thành thục thì kém hiệu quả.</strong> Nghe giảng lại thứ mình đã biết vừa chán vừa không tạo tiến bộ. Người đã có nền học nhiều hơn từ việc tự vật lộn với bài khó. <strong>Dễ trượt thành thầy nói trò chép.</strong> Direct instruction đúng nghĩa có mật độ tương tác rất cao — hỏi liên tục, kiểm tra liên tục. Bỏ phần đó đi thì chỉ còn lại một bài thuyết trình, và nó không hiệu quả. <strong>Không tự sinh ra động lực.</strong> Nó dạy hiệu quả, nhưng không trả lời câu hỏi &quot;học cái này để làm gì&quot;. Cần thứ khác gánh phần đó. <strong>Không hợp với mục tiêu mở.</strong> Sáng tạo, đặt câu hỏi hay, tự chọn hướng nghiên cứu — không thể dạy thẳng những thứ này.</p><h2 id="đinh-kien-đang-go-​" tabindex="-1">Định kiến đáng gỡ <a href="#đinh-kien-đang-go">​</a> <a class="header-anchor" href="#đinh-kien-đang-go-​" aria-label="Permalink to &quot;Định kiến đáng gỡ [​](#đinh-kien-đang-go)&quot;">​</a></h2><p>Direct instruction thường bị coi là &quot;lạc hậu&quot;, đối lập với các phương pháp &quot;tiến bộ&quot;. Sự đối lập này gây hại nhiều hơn có ích. Bằng chứng nhất quán trong nhiều thập kỷ: <strong>với người mới bắt đầu, hướng dẫn trực tiếp thắng khám phá tự do</strong>. Sự đối lập thật không phải &quot;cũ và mới&quot;, mà là &quot;learner đang ở giai đoạn nào&quot;. Cùng một learner, cùng một môn: cần direct instruction ở chương mới, và cần inquiry ở chương đã có nền. Chọn phe là chọn sai một nửa số tình huống.</p><h2 id="nemo12-dung-no-o-đau-​" tabindex="-1">Nemo12 dùng nó ở đâu <a href="#nemo12-dung-no-o-đau">​</a> <a class="header-anchor" href="#nemo12-dung-no-o-đau-​" aria-label="Permalink to &quot;Nemo12 dùng nó ở đâu [​](#nemo12-dung-no-o-đau)&quot;">​</a></h2><p>Ở chế độ <strong>Guided</strong> và ở các <strong>bài mẫu giải sẵn</strong> — dành cho learner mới gặp một khái niệm, hoặc đã thất bại nhiều lần với cách tiếp cận khác. Quan trọng: đây là quyết định theo <strong>từng mảng kiến thức</strong>, không theo learner. Một học sinh giỏi vẫn vào chế độ Guided khi gặp chủ đề hoàn toàn mới. Nemo12 không dán nhãn &quot;học sinh cần dạy kỹ&quot; lên bất kỳ đứa trẻ nào. Ở nhà Nếu bạn định giảng cho con, hãy nói to suy nghĩ của mình thay vì chỉ trình bày lời giải: <em>&quot;Đọc đề xong mẹ nghĩ ngay tới… vì…&quot;</em>. Và đừng hỏi &quot;con hiểu chưa&quot;. Hỏi một câu mà chỉ người hiểu mới trả lời được. Dạy thẳng không phải kém tiến bộ. Nó là cách nhanh nhất để một người mới có được cái nền mà mọi phương pháp khác đều cần tới. <a href="/ideas/project-based">Project-based Learning →</a></p>',14)])])}const d=t(a,[["render",r]]);export{l as __pageData,d as default};
